NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Micah'

CHAPTERS = {
    1: {
        1: 'Das Wort Jehovahs, das geschah an Michah, den Moraschthiter, in den Tagen Jothams, Achas, Jechiskijahs, der Könige von Judah, das er schaute über Schomron und Jerusalem.',
        2: 'Höret, ihr Völker allzumal, horche, o Erde und ihre Fülle; und zum Zeugen sei wider euch der Herr Jehovah, der Herr aus dem Tempel Seiner Heiligkeit.',
        3: 'Denn siehe, Jehovah geht aus von Seinem Ort und steigt herab und tritt auf der Erde Höhen;',
        4: 'Daß unter Ihm die Berge schmelzen und Talgründe sich spalten, wie Wachs vor dem Feuer, wie Wasser, das man auf den Abhang hingießt.',
        5: 'Wegen Jakobs Übertretung ist alles dies und wegen der Sünden des Hauses Israel. Was ist die Übertretung Jakobs? Ist es nicht Schomron? Und was Jehudahs Opferhöhen? Ist es nicht Jerusalem?',
        6: 'Und zum Trümmerhaufen auf dem Felde mache Ich Schomron, zu Pflanzungen eines Weinbergs, und gieße seine Steine in die Schlucht hin, und decke seine Grundfesten auf.',
        7: 'Zerstoßen werden alle ihre Schnitzbilder, und verbrannt im Feuer alle ihre Buhlgaben, und alle ihre Götzenbilder setze Ich in Verwüstung, denn von der Buhlgabe einer Buhlerin hat sie es zusammengebracht, und zu den Buhlgaben einer Buhlerin kehren sie zurück.',
        8: 'Darüber klage und heule ich, gehe ausgebeutet und nackt daher, mache eine Klage wie die Drachen, und trauere wie die jungen Eulen.',
        9: 'Denn verzweifelt sind ihre Schläge, denn bis Jehudah kommt er, berührt Meines Volkes Tor bis an Jerusalem.',
        10: 'In Gath sagt es nicht an mit Weinen, weint nicht im Hause Aphras! Wälze dich umher im Staube!',
        11: 'Ziehet für euch hinüber, Einwohnerschaft Schaphirs, entblößt mit Scham. Nicht komm heraus, die du in Zaanan wohnest. Die Klage von Beth-Haezel nehme ihren Stand von euch.',
        12: 'Denn die Bewohnerin von Maroth wartet auf Gutes; denn von Jehovah kam Böses herab bis an das Tor von Jerusalem.',
        13: 'Schirre den Renner an den Streitwagen, Bewohnerin von Lachisch, Anfängerin der Sünde ist sie für Zijons Tochter; denn in dir fanden sich die Übertretungen Israels.',
        14: 'Darum tue Verzicht auf den Erbbesitz Gaths; die Häuser Achsibs sind eine Täuschung für Israels Könige.',
        15: 'Noch bringe Ich dir den Erbbesitzer herein, Mareschahs Wohnerschaft. Bis Adul- lam wird kommen Israels Herrlichkeit.',
        16: 'Mache dich kahl und schere dich ob den Söhnen deiner Wonne; mache deine Kahlheit breit, wie der Adler; denn sie sind von dir weggeführt.',
    },
    2: {
        1: 'Wehe denen, die auf Unrecht denken, die Böses auf ihren Lagern wirken, am Licht des Morgens es tun, weil ihre Hand ihnen zum Gotte ist.',
        2: 'Und sie begehren Felder und entreißen sie, und Häuser, und nehmen sie weg; und sie bedrücken den Mann und sein Haus, und den Mann und sein Erbe.',
        3: 'Darum, so spricht Jehovah: Siehe, Ich denke auf Böses wider diese Familie, aus der ihr eure Hälse nicht herausziehen sollet, daß ihr aufrecht ginget; denn es ist eine Zeit des Bösen.',
        4: 'An jenem Tage erhebt man einen Spruch über euch und stimmt ein Trauerlied an: Es ist vorbei! spricht man. Mit Verheerung sind wir verheert. Das Teil meines Volkes wird vertauscht. Wie entzieht er es mir, und teilt unsere Felder an die Abtrünnigen aus!',
        5: 'Darum wird keiner sein, der in der Versammlung Jehovahs dir die Meßschnur zum Lose werfe.',
        6: 'Sie faseln: Ihr sollt nicht weissagen! Sie sollen nicht von solchem weissagen! Die Schande wird nicht zurückweichen!',
        7: 'Darf man so sprechen, Jakobs Haus? Ist der Geist Jehovahs verkürzt? Sind das Seine Taten? Sind Meine Worte nicht gut mit dem, der da gerade wandelt?',
        8: 'Aber zum Feinde hat sich Mein Volk Mir entgegen aufgestellt wegen des Gewandes, den Mantel zieht ihr denen aus, die sicher vorüberziehen, die vom Streite zurückkehren.',
        9: 'Die Weiber Meines Volkes vertreibt ihr jede aus dem Hause ihrer Wonne, nehmt ihren Kindlein Meine Ehre ewiglich.',
        10: 'Steht auf und geht hin! Dies ist kein Ruheort. Wegen der Unreinheit wird sie euch heillos verstören.',
        11: 'Ja, ein Mann, der im Geiste wandelt, und mit Lüge täuscht: Ich will dir mit Wein und starkem Getränk wahrsagen! das wäre ein Wahrsagen für dieses Volk!',
        12: 'Versammeln werde Ich dich, Jakob, allzumal, zusammenbringen den Überrest von Israel, sie zusammenstellen wie Bozrahs Herde, wie einen Trieb inmitten seines Weideplatzes: sie dröhnen mit Menschen.',
        13: 'Vor ihnen geht der Durchbrecher herauf. Sie brechen durch und ziehen durch das Tor und ziehen dadurch aus, und vor ihnen her zieht ihr König vorüber, und Jehovah ihnen zum Haupt.',
    },
    3: {
        1: 'Und ich sprach: Höret doch, ihr Häupter Jakobs, und ihr Anführer vom Hause Israel: Ist es nicht an euch, das Recht zu wissen?',
        2: 'Die ihr das Gute hasset und liebt das Böse, ihr reißt ab von ihnen die Haut und ihr Fleisch von ihrem Gebein!',
        3: 'Und die das Fleisch von Meinem Volk gegessen, und habt die Haut ihm abgezogen, und zerzahnt sein Gebein und es zerlegt, wie in den Topf, und wie Fleisch in der Mitte eines Kessels.',
        4: 'Dann werden sie schreien zu Jehovah, und Er wird ihnen nicht antworten und wird vor ihnen Sein Angesicht verbergen zu jener Zeit, so wie sie böse machten ihr Tun.',
        5: 'So spricht Jehovah wider die Propheten, die Mein Volk irre führen, die mit ihren Zähnen beißen und rufen Frieden aus; und wer ihnen nichts gibt vor ihren Mund, wider den heiligen sie den Streit..',
        6: 'Darum habt ihr statt des Gesichtes Nacht, und Finsternis habt ihr statt Wahrsagung, und über den Propheten geht die Sonne unter, und verdunkelt wird über ihnen der Tag.',
        7: 'Und die Seher werden beschämt, und die Wahrsager erröten, und über den Bart verhüllen alle sich, weil keine Antwort Gottes da ist.',
        8: 'Aber ich jedoch bin erfüllt mit Kraft, mit dem Geiste Jehovahs und mit Recht und Macht, um Jakob seine Übertretung anzusagen und Israel seine Sünde.',
        9: 'Höret doch dies, ihr Häupter des Hauses Jakob, und ihr Anführer vom Hause Israel,denen das Recht zum Greuel ist, und die krumm machen alles, was gerade ist;',
        10: 'Die ihr Zijon mit Blut bauet und Jerusalem mit Verkehrtheit.',
        11: 'Es richten ihre Häupter um ein Geschenk, und ihre Priester unterweisen um das Entgelt, und ihre Propheten wahrsagen um Silber, und stützen auf Jehovah sich und sagen: Ist nicht Jehovah unter uns, kein Übel kommt über uns.',
        12: 'Darum wird euretwegen Zijon als Feld bepflügt und Jerusalem zum Trümmerhaufen werden und der Berg des Hauses zu Opferhöhen des Waldes.',
    },
    4: {
        1: 'Und in den letzten der Tage wird geschehen, daß der Berg des Hauses Jehovahs feststehen wird als das Haupt der Berge und erhaben über den Hügeln, und Völker auf ihn strömen.',
        2: 'Und viel Völkerschaften werden gehen und sprechen: Laßt uns gehen und hinaufziehen zum Berg Jehovahs und zum Hause des Gottes Jakobs, daß Er uns unterweise in Seinen Wegen, und wir wandeln auf Seinen Pfaden; denn von Zijon geht das Gesetz aus, und das Wort Jehovahs von Jerusalem.',
        3: 'Und richten wird Er zwischen vielen Völkern und rügen mächtige Völkerschaften in die Ferne; und ihre Schwerter schmieden sie zu Hacken und ihre Spieße zu Winzermessern. Nicht wird das Schwert erheben Völkerschaft wider Völkerschaft; und nicht lernen fürder sie den Streit.',
        4: 'Und jeder Mann sitzt unter seinem Weinstock und unter seinem Feigenbaum, und niemand scheucht auf; denn der Mund Jehovahs der Heerscharen hat es geredet.',
        5: 'Denn alle Völker werden, jedes im Namen seines Gottes, wandeln, und wir werden im Namen Jehovahs, unseres Gottes, wandeln in Ewigkeit und immerfort.',
        6: 'An jenem Tage, spricht Jehovah, will sammeln Ich, was hinkt, und das Verstoßene zusammenbringen, und dem Ich Übles getan.',
        7: 'Und das Hinkende werde Ich zum Überrest setzen, und das Versprengte zu zahlreicher Völkerschaft, und König wird sein über sie Jehovah auf dem Berge Zijon von nun an und bis in Ewigkeit.',
        8: 'Und du, der Herde Turm, Anhöhe der Tochter Zijons, zu dir wird kom- men und eingehen die frühere Herrschaft, das Reich der Tochter Jerusalems.',
        9: 'Nun, was schreist du so laut? Ist kein König in dir? Ist dein Ratgeber verloren? Daß eine Wehe dich erfaßt wie die Gebärerin?',
        10: 'Habe Wehen und lasse hervorbrechen, Tochter Zijons, wie die Gebärerin, denn nun ziehst du aus von der Hauptstadt, und wohnst im Felde, und kommst bis Babel! Dort wirst du errettet, dort erlöst dich Jehovah aus der Hand deiner Feinde.',
        11: 'Und jetzt sammeln sich viele Völkerschaften wider dich, die sprechen: Sie wird entheiligt, daß unser Auge auf Zion schaue.',
        12: 'Sie aber wissen die Gedanken Jehovahs nicht, und verstehen Seinen Ratschluß nicht; denn wie die Garbe bringt Er sie auf die Tenne zusammen.',
        13: 'Stehe auf und drisch, du Tochter Zijons; denn dein Horn will Ich von Eisen machen, und deine Hufe will von Erz Ich machen, daß du zermalmst viele Völker; und ihren Gewinn verbanne Ich dem Jehovah und ihr Vermögen dem Herrn der ganzen Erde. Nun sammle deinen Kriegshaufen, du Tochter der Kriegshaufen! Denn ein Bollwerk macht man wider uns. Sie schlagen mit der Rute auf den Backen den Richter Israels.',
    },
    5: {
        1: 'Und du, Bethlehem Ephratha, bist klein, zu sein unter den Tausenden Jehudahs: Aus dir soll Mir hervorgehen, Der in Israel soll Herrscher sein, und Dessen Ausgänge von der Vorzeit sind, von den Tagen der Ewigkeit.',
        2: 'Darum gibt Er sie dahin bis auf die Zeit, da die, so gebären soll, geboren hat. Und die übrig sind von Seinen Brüdern, zurückkehren zu den Söhnen Israels.',
        3: 'Und Er wird stehen und weiden in der Stärke Jehovahs und in der Hoheit des Namens Jehovahs, Seines Gottes, und sie werden sitzen, denn jetzt wird Er groß werden bis an der Erde Äußerstes.',
        4: 'Und dies wird sein der Friede: Wenn Aschur kommt in unser Land, daß unsere Paläste es betrete, so stellen wir sieben Hirten wider ihn auf und acht Gesalbte der Menschen.',
        5: 'Und sie werden Aschurs Land mit dem Schwerte weiden und Nimrods Land an seinen Pforten, und Er wird erretten von Aschur, wenn Er kommt in unser Land und unsere Grenze betritt.',
        6: 'Und Jakobs Überrest wird inmitten vieler Völker sein, wie der Tau von Jehovah, wie Regenschauer auf das Kraut, der nicht harrt auf den Mann, und nicht wartet auf des Menschen Söhne.',
        7: 'Und Jakobs Überrest wird unter den Völkerschaften sein inmitten vieler Völker wie der Löwe unter des Waldes Tieren, wie der junge Löwe unter den Trieben der Herde, der, wenn er hindurchgeht, zerstampft und zerfleischt, und niemand errettet.',
        8: 'Erhöht wird deine Hand über deine Dränger, und alle deine Feinde sollen ausgerottet werden.',
        9: 'Und am selben Tage wird geschehen, spricht Jehovah, daß deine Rosse Ich aus deiner Mitte ausrotten und deine Streitwagen zerstören werde.',
        10: 'Und deines Landes Städte rotte Ich aus und reiße alle deine Festungen ein.',
        11: 'Und Ich werde ausrotten aus deiner Hand die Zaubereien; und Zeichendeuter sollen nicht bei dir sein.',
        12: 'Und deine Schnitzbilder und deine Bildsäulen rotte Ich aus deiner Mitte aus, und du sollst nicht mehr anbeten deiner Hände Werk.',
        13: 'Und deine Ascheren rode Ich aus aus deiner Mitte und vernichte deine Städte.',
        14: 'Und tue Rache mit Zorn und mit Grimm an den Völkerschaften, die nicht gehorchen.',
    },
    6: {
        1: 'Höret doch, was Jehovah spricht: Stehe auf, hadere mit den Bergen, und laß die Hügel deine Stimme hören!',
        2: 'Höret, ihr Berge, Jehovahs Hader, und ihr starken Grundfesten der Erde; denn Hader hat Jehovah mit Seinem Volk und rügt Israel.',
        3: 'Mein Volk, was habe Ich dir getan? Womit habe Ich dich ermüdet? antworte wider Mich!',
        4: 'Daß Ich dich aus dem Lande Ägypten heraufgebracht, und aus dem Haus der Knechte dich habe eingelöst, und Moses, Aharon und Mirjam vor dir hergesandt?',
        5: 'Gedenke doch, Mein Volk, was Balak, Moabs König, beriet, und was ihm Bileam, Beors Sohn, antwortete, von Schittim bis Gilgal; daß man erkenne die Gerechtigkeit Jehovahs.',
        6: 'Womit soll ich zuvorkommen dem Jehovah, mich beugen vor dem Gott der Höhe? Soll ich Ihm zuvorkommen mit Brandopfern, mit einjährigen Kälbern?',
        7: 'Hat Jehovah Wohlgefallen an tausenden von Widdern, an zehntausenden von Bächen Öls? Soll meinen Erstgeborenen ich geben für meine Übertretung, für meiner Seele Sünde meines Leibes Frucht?',
        8: 'Er hat dir angesagt, o Mensch, was gut ist. Und was fordert Jehovah von dir, als das Recht zu tun und Barmherzigkeit zu lieben, und in Demut zu wandeln vor deinem Gott.',
        9: 'Jehovahs Stimme ruft der Stadt, und Weisheit ist es, zu fürchten Deinen Namen. Hört auf den Stab und Ihn, Der ihn bestellt.',
        10: 'Sind nicht noch im Haus des Ungerechten der Ungerechtigkeit Schätze, und das magere Ephah, das verfluchte?',
        11: 'Sollte Ich lautersprechen sie mit der ungerechten Waage und mit dem Beutel, mit Gewichten des Betrugs?',
        12: 'Wo die Reichen voll sind von Gewalttat, und deren Einwohner Lüge reden, und deren Zunge Trug ist in ihrem Munde?',
        13: 'Und auch Ich bin müde, dich zu schlagen, dich zu verwüsten ob deinen Sünden.',
        14: 'Du sollst essen und nicht satt werden, und dein Heißhunger wird in deinem Inneren sein. Und was du entrückst, sollst du nicht sichern, und was du sicherst, gebe Ich dem Schwerte.',
        15: 'Säen wirst du und nicht ernten, wirst Oliven treten und nicht mit Öl dich salben, und Most und doch nicht Wein trinken!',
        16: 'Und ihr haltet zu Omris Satzungen und allem Tun des Hauses Achab, und wandelt nach ihren Ratschlägen, auf daß Ich euch hingebe der Verwüstung, und die, so in ihr wohnen, dem Gezisch, und ihr die Schmach Meines Volkes tragt.',
    },
    7: {
        1: 'Wehe mir, mir wird es wie beim Sammeln der Sommerfrüchte, wie wenn man nachliest in der Weinernte: keine Traube zum Essen. Nach der Frühfeige gelüstet meine Seele.',
        2: 'Vergangen ist der Heilige von der Erde, und kein Redlicher ist da mehr unter den Menschen. Sie alle lauern auf Blut, sie jagen, jeder Mann den Bruder ins Garn.',
        3: 'Beide Hände sind aus zum Bösestun statt Gutes zu tun. Der Oberste fordert und der Richter um Vergeltung, und der Große redet die Verstörtheit seiner Seele, und sie verflechten es.',
        4: 'Der Gute von ihnen ist wie der Dorn, der Redliche wie die Dornhecke. Deiner Wächter Tag, deine Heimsuchung ist gekommen; nun ist Verworrenheit unter ihnen.',
        5: 'Glaubt dem Genossen nicht, vertraut nicht dem Stammhaupt. Vor ihr, die an deinem Busen liegt, hüte die Pforte deines Mundes.',
        6: 'Denn der Sohn verunehrt den Vater, die Tochter steht wider ihre Mutter auf, die Schnur wider ihre Schwieger, Feinde des Mannes sind die Männer seines Hauses.',
        7: 'Ich aber spähe auf zu Jehovah, will warten auf den Gott meines Heils, mein Gott wird mich erhören.',
        8: 'Sei nicht froh, meine Feindin, über mich! Bin ich gefallen, stehe ich wieder auf; sitze ich in Finsternis, so ist Jehovah mir ein Licht.',
        9: 'Das Grollen Jehovahs will ich tragen; denn ich sündigte an Ihm, bis daß Er hadert meinen Hader, und mir Recht schafft, mich ans Licht herausbringt; ich werde Seine Gerechtigkeit sehen.',
        10: 'Daß meine Feindin es sehe und Scham decke sie, die zu mir sprach: Wo ist Jehovah, dein Gott? Meine Augen werden auf sie sehen; nun werden sie zerstampft wie der Kot der Gassen.',
        11: 'Der Tag ist da, deine Mauern zu bauen, an jenem Tag wird ferne sein die Satzung.',
        12: 'An jenem Tag kommt man bis zu dir von Aschur und Ägyptens Städten, und von Ägypten und bis zum Flusse und vom Meer zum Meer und von Berg zu Berg.',
        13: 'Aber zur Verwüstung wird das Land um seiner Bewohner willen, ob ihrer Werke Frucht.',
        14: 'Weide dein Volk mit deiner Rute, die Herde deines Erbes, die einsam im Walde wohnt, inmitten Karmels; in Baschan sollen sie weiden und in Gilead, wie in der Ewigkeit Tagen.',
        15: 'Wie in den Tagen, da du auszogst aus dem Land Ägypten, will Ich es Wunder sehen lassen.',
        16: 'Es werden es die Völkerschaften sehen und sich schämen mit aller ihrer Macht, sie werden die Hand auf den Mund legen und ertauben ihre Ohren.',
        17: 'Sie werden Staub lecken wie die Schlange, wie die Kriechtiere der Erde hervorzittern aus ihren Verschlüssen, schaudernd sich nahen Jehovah, unserem Gotte, und sich fürchten vor Dir.',
        18: 'Wer ist ein Gott wie Du, Der Missetat vergibt und vorbeigeht an der Übertretung dem Überreste Seines Erbes; der Seinen Zorn nicht immerfort festhält, weil Er Lust hat an Barmherzigkeit?',
        19: 'Er kehrt zurück, Sich unser zu erbarmen, unsere Missetaten zu unterwerfen; und Er wirft alle ihre Sünden in des Meeres Schlünde.',
        20: 'Du wirst dem Jakob Wahrheit geben, dem Abraham Barmherzigkeit, die Du seit der Vorzeit Tagen unseren Vätern geschworen hast.',
    },
}
